package com.example.lura.playback

object SleepSoundPlaybackCatalog {
    private const val MOCK_TEST_AUDIO_URI =
        "data:audio/wav;base64,"

    private val localSourceUris = emptyMap<String, String>()

    fun sourceUriFor(soundId: String): String =
        localSourceUris[soundId] ?: MOCK_TEST_AUDIO_URI
}
